select `ni`.`nin_id_planilla` AS `nin_id_planilla`,`p`.`ppl_numero` AS `planilla`,`p`.`ppl_estado_proceso` AS `estado_planilla`,`j`.`jub_correlativo` AS `id_jubilado`,`j`.`jub_dpi` AS `jub_dpi`,concat(`j`.`jub_nombres`,' ',`j`.`jub_apellidos`) AS `nombre_completo`,`j`.`jub_fecha_jubilacion` AS `jub_fecha_jubilacion`,`ni`.`nin_dias_trabajados` AS `dias_trabajados`,`ni`.`nin_valor_teorico` AS `pension_teorica`,`ni`.`nin_porcentaje_aplicado` AS `porcentaje`,`ni`.`nin_pago_corriente` AS `pago_corriente`,`ni`.`nin_abono_historico` AS `abono_historico`,`apa`.`apa_periodo_deuda` AS `periodo_aplicado`,`ni`.`nin_valor` AS `total_ingreso`,coalesce((select sum(`apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_valor`) from `apps_rpjepq`.`rpj_prc_nomina_descuento` where `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_planilla` = `ni`.`nin_id_planilla` and `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_jubilado` = `ni`.`nin_id_jubilado`),0) AS `total_descuentos`,`ni`.`nin_valor` - coalesce((select sum(`apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_valor`) from `apps_rpjepq`.`rpj_prc_nomina_descuento` where `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_planilla` = `ni`.`nin_id_planilla` and `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_jubilado` = `ni`.`nin_id_jubilado`),0) AS `neto_a_pagar` from (((`apps_rpjepq`.`rpj_prc_nomina_ingreso` `ni` join `apps_rpjepq`.`rpj_cat_parametro_planilla` `p` on(`p`.`ppl_correlativo` = `ni`.`nin_id_planilla`)) join `apps_rpjepq`.`rpj_mnt_jubilado` `j` on(`j`.`jub_correlativo` = `ni`.`nin_id_jubilado`)) left join `apps_rpjepq`.`rpj_prc_aplicacion_pago` `apa` on(`apa`.`apa_id_planilla` = `ni`.`nin_id_planilla` and `apa`.`apa_id_jubilado` = `ni`.`nin_id_jubilado`)) where `ni`.`nin_tipo_manejo` = 2
